pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(100, "Test", "TST"); }
    function testFuzz_property(address attacker, uint256 burnAmount) public {
        vm.assume(attacker != address(0));
        vm.assume(burnAmount > 0);
        // Record owner before any attack
        address ownerBefore = c.owner();
        // Attacker calls owned() to become owner (possible in buggy version)
        vm.prank(attacker);
        c.owned();
        // Now caller tries to burn as that attacker
        vm.prank(attacker);
        // Approve some balance for attacker; we need attacker to have tokens to burn
        // Since totalSupply was minted to deployer, we transfer some to attacker first
        // For burn to succeed, the attacker must have balance; only deployer (owner initially) can transfer
        if (attacker != c.owner()) {
            // Deployer transfers tokens to attacker so attacker can attempt burn
            vm.prank(c.owner());
            c.transfer(attacker, burnAmount);
        } else {
            // If attacker is the deployer, he already has tokens
        }
        // Now attacker tries to burn (onlyOwner guarded, will fail if attacker is not owner, but bug allows attacker to become owner via owned())
        // In reference, owned() only works for owner, so attacker cannot become owner and burn will fail (or revert).
        // In mutant, owned() works for anyone, so attacker becomes owner and burn succeeds, reducing totalSupply and changing owner if burn modifies owner (it doesn't directly, but the owner state changed via owned()).
        // The invariant is: owner remains the same as before if the caller is not the original owner.
        try c.burn(burnAmount) {
            // If burn succeeded, check owner did not change from original unless caller was original owner
            assertTrue(c.owner() == ownerBefore || attacker == ownerBefore);
        } catch {
            // If burn failed, owner must be unchanged
            assertTrue(c.owner() == ownerBefore);
        }
    }
}

