pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, uint256 burnAmount, address burner) public {
        vm.assume(initialSupply > 0 && initialSupply < 1e50);
        vm.assume(burnAmount > 0 && burnAmount <= initialSupply);
        vm.assume(burner != address(0));

        // Reset contract state: redeploy with initialSupply
        c = new C(initialSupply, "Test", "TST");
        // Total supply should be equal to initialSupply (decimals=0)
        uint256 totalBefore = c.totalSupply();
        vm.assume(totalBefore == initialSupply);

        // Give burner the full supply
        vm.prank(address(this));
        c.transfer(burner, initialSupply);

        // Burn from burner account
        vm.prank(address(this));
        c.mintToken(address(this), 1); // to have enough to satisfy onlyOwner requirement, we burn as owner
        vm.startPrank(address(this));
        c.burn(burnAmount);
        vm.stopPrank();

        // Compute sum of balances (need to iterate? only test two known addresses: address(this) and burner)
        // Since we cannot iterate all addresses, we trust the contract-level invariant: totalSupply should equal sum of all balances.
        // But we can only check the two addresses we know. However, totalSupply must be >= sum of known balances.
        // A stronger check: after burn, totalSupply must be initialSupply - burnAmount.
        assertTrue(c.totalSupply() == initialSupply - burnAmount);
    }
}

